76	async function embedHierarchyHandler(
77	  input: Record<string, unknown>,
78	  context?: ToolContext
79	): Promise<MCPToolResult> {
80	  const logger = context?.logger ?? defaultLogger;
81	  const startTime = performance.now();
82	
83	  try {
84	    const validationResult = EmbedHierarchyInputSchema.safeParse(input);
85	    if (!validationResult.success) {
86	      return errorResult(`Invalid input: ${validationResult.error.message}`);
87	    }
88	
89	    const data = validationResult.data;
90	    logger.debug('Embed hierarchy', {
91	      nodes: data.hierarchy.nodes.length,
92	      model: data.model,
93	      dimensions: data.parameters?.dimensions,
94	    });

95	
96	    // Validate size
97	    if (data.hierarchy.nodes.length > RESOURCE_LIMITS.MAX_NODES) {
98	      return errorResult(`Too many nodes: ${data.hierarchy.nodes.length} > ${RESOURCE_LIMITS.MAX_NODES}`);
99	    }
100	
101	    const bridge = await getHyperbolicBridge();
102	    const result = await bridge.embedHierarchy(data.hierarchy, data.parameters);
103	
104	    // Store for later use
105	    const indexId = `embed_${Date.now()}`;
106	    embeddingStore.set(indexId, result);
107	
108	    // Create index for search
109	    bridge.createIndex(indexId, result.dimension, result.curvature);
110	    for (const [nodeId, point] of result.embeddings) {
111	      bridge.addToIndex(indexId, nodeId, point);
112	    }
113	
114	    const duration = performance.now() - startTime;
115	    logger.info('Hierarchy embedded', {
116	      nodes: result.embeddings.size,
117	      curvature: result.curvature,
118	      mapScore: result.metrics.mapScore,
119	      durationMs: duration.toFixed(2),
120	    });
121	
122	    // Convert embeddings to serializable format
123	    const embeddingsList: Array<{ id: string; coordinates: number[]; depth: number }> = [];
124	    for (const [nodeId, point] of result.embeddings) {
125	      embeddingsList.push({
126	        id: nodeId,
127	        coordinates: Array.from(point.coordinates).slice(0, 5), // First 5 dimensions
128	        depth: bridge.hierarchyDepth(point),
129	      });
130	    }
131	
132	    return successResult({
133	      indexId,
134	      model: result.model,
135	      curvature: result.curvature,
136	      dimension: result.dimension,
137	      metrics: result.metrics,
138	      embeddings: embeddingsList.slice(0, 20), // Sample of embeddings
139	      totalNodes: result.embeddings.size,
140	    });
141	  } catch (error) {
142	    logger.error('Embedding failed', { error: error instanceof Error ? error.message : String(error) });
143	    return errorResult(error instanceof Error ? error : new Error(String(error)));
144	  }
145	}
